-- create "preview_conversions" table
CREATE TABLE `preview_conversions` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, `status` text NOT NULL, `retry_count` integer NOT NULL DEFAULT (0), `last_attempted_at` datetime NULL, `next_attempt_at` datetime NULL, `processing_started_at` datetime NULL, `failure_category` text NULL, `created_by` integer NULL, `updated_by` integer NULL, `source_stored_file_id` integer NOT NULL, `preview_stored_file_id` integer NULL, CONSTRAINT `preview_conversions_users_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE NO ACTION, CONSTRAINT `preview_conversions_users_updater` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE NO ACTION, CONSTRAINT `preview_conversions_stored_files_source` FOREIGN KEY (`source_stored_file_id`) REFERENCES `stored_files` (`id`) ON DELETE NO ACTION, CONSTRAINT `preview_conversions_stored_files_preview` FOREIGN KEY (`preview_stored_file_id`) REFERENCES `stored_files` (`id`) ON DELETE SET NULL);
-- create index "previewconversion_source_stored_file_id" to table: "preview_conversions"
CREATE UNIQUE INDEX `previewconversion_source_stored_file_id` ON `preview_conversions` (`source_stored_file_id`);
-- create index "previewconversion_status_next_attempt_at_id" to table: "preview_conversions"
CREATE INDEX `previewconversion_status_next_attempt_at_id` ON `preview_conversions` (`status`, `next_attempt_at`, `id`);
